-- Seed the effective general-quiz dataset used by /api/quiz/random.
--
-- Legal source chain: MySQL Flyway V72/V73, V92, and V120, followed by the
-- cleanup/workflow/normalization rules in V85, V95, V96, V107, V119,
-- V197, V199, V202, V204, and V208-V213/V235. The resulting functional
-- dataset is 50 active PUBLISHED questions and 131 deliverable options.
--
-- Stable source_ref values exist only inside this migration. Production
-- relationships are resolved through category.code and the complete
-- multilingual question natural key; no MySQL numeric IDs are assumed.

CREATE TEMPORARY TABLE general_quiz_question_seed (
    source_ref VARCHAR(30) PRIMARY KEY,
    category_code VARCHAR(10) NOT NULL,
    question_ar TEXT NOT NULL,
    question_en TEXT NOT NULL,
    question_nl TEXT NOT NULL,
    question_fr TEXT NOT NULL,
    question_type VARCHAR(20) NOT NULL,
    difficulty_level VARCHAR(10) NOT NULL,
    content_image_url TEXT,
    explanation_ar TEXT,
    explanation_en TEXT,
    explanation_nl TEXT,
    explanation_fr TEXT,
    error_explanation_ar TEXT,
    error_explanation_en TEXT,
    error_explanation_nl TEXT,
    error_explanation_fr TEXT,
    typical_error_type VARCHAR(30),
    context_specific BOOLEAN NOT NULL,
    requires_sign_image BOOLEAN NOT NULL,
    is_active BOOLEAN NOT NULL,
    status VARCHAR(20) NOT NULL
) ON COMMIT DROP;

