DO $$
BEGIN
    IF (SELECT COUNT(*) FROM general_quiz_question_seed) <> 50 THEN
        RAISE EXCEPTION 'General quiz seed must contain exactly 50 questions';
    END IF;
    IF (SELECT COUNT(*) FROM general_quiz_option_seed) <> 131 THEN
        RAISE EXCEPTION 'General quiz seed must contain exactly 131 options';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM general_quiz_question_seed seed
        LEFT JOIN categories category ON category.code = seed.category_code
        WHERE category.id IS NULL
    ) THEN
        RAISE EXCEPTION 'General quiz seed references an unknown category code';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM general_quiz_option_seed
        GROUP BY question_source_ref
        HAVING COUNT(*) NOT BETWEEN 2 AND 3
           OR COUNT(*) FILTER (WHERE is_correct) <> 1
    ) THEN
        RAISE EXCEPTION 'Every general quiz question must have 2-3 options and exactly one correct option';
    END IF;
END;
$$;

INSERT INTO quiz_questions (
    question_ar, question_en, question_nl, question_fr,
    question_type, difficulty_level, category_id, content_image_url,
    explanation_ar, explanation_en, explanation_nl, explanation_fr,
    error_explanation_ar, error_explanation_en, error_explanation_nl, error_explanation_fr,
    typical_error_type, context_specific, requires_sign_image,
    is_active, status, published_at
)
SELECT
    seed.question_ar, seed.question_en, seed.question_nl, seed.question_fr,
    seed.question_type, seed.difficulty_level, category.id, seed.content_image_url,
    seed.explanation_ar, seed.explanation_en, seed.explanation_nl, seed.explanation_fr,
    seed.error_explanation_ar, seed.error_explanation_en,
    seed.error_explanation_nl, seed.error_explanation_fr,
    seed.typical_error_type, seed.context_specific, seed.requires_sign_image,
    seed.is_active, seed.status,
    CASE WHEN seed.status = 'PUBLISHED' THEN CURRENT_TIMESTAMP ELSE NULL END
FROM general_quiz_question_seed seed
JOIN categories category ON category.code = seed.category_code
WHERE NOT EXISTS (
    SELECT 1
    FROM quiz_questions existing
    WHERE existing.question_ar = seed.question_ar
      AND existing.question_en = seed.question_en
      AND existing.question_nl = seed.question_nl
      AND existing.question_fr = seed.question_fr
);

INSERT INTO quiz_answer_options (
    question_id,
    option_text_ar, option_text_en, option_text_nl, option_text_fr,
    is_correct, display_order
)
SELECT
    question.id,
    option_seed.option_text_ar, option_seed.option_text_en,
    option_seed.option_text_nl, option_seed.option_text_fr,
    option_seed.is_correct, option_seed.display_order
FROM general_quiz_option_seed option_seed
JOIN general_quiz_question_seed question_seed
  ON question_seed.source_ref = option_seed.question_source_ref
JOIN quiz_questions question
  ON question.question_ar = question_seed.question_ar
 AND question.question_en = question_seed.question_en
 AND question.question_nl = question_seed.question_nl
 AND question.question_fr = question_seed.question_fr
WHERE NOT EXISTS (
    SELECT 1
    FROM quiz_answer_options existing
    WHERE existing.question_id = question.id
      AND existing.display_order = option_seed.display_order
);

DO $$
DECLARE
    matched_questions INTEGER;
    matched_options INTEGER;
BEGIN
    SELECT COUNT(*)
      INTO matched_questions
      FROM general_quiz_question_seed seed
      JOIN quiz_questions question
        ON question.question_ar = seed.question_ar
       AND question.question_en = seed.question_en
       AND question.question_nl = seed.question_nl
       AND question.question_fr = seed.question_fr
     WHERE question.is_active = TRUE
       AND question.status = 'PUBLISHED';

    SELECT COUNT(*)
      INTO matched_options
      FROM general_quiz_option_seed option_seed
      JOIN general_quiz_question_seed question_seed
        ON question_seed.source_ref = option_seed.question_source_ref
      JOIN quiz_questions question
        ON question.question_ar = question_seed.question_ar
       AND question.question_en = question_seed.question_en
       AND question.question_nl = question_seed.question_nl
       AND question.question_fr = question_seed.question_fr
      JOIN quiz_answer_options option
        ON option.question_id = question.id
       AND option.display_order = option_seed.display_order
       AND option.option_text_ar = option_seed.option_text_ar
       AND option.option_text_en = option_seed.option_text_en
       AND option.option_text_nl = option_seed.option_text_nl
       AND option.option_text_fr = option_seed.option_text_fr
       AND option.is_correct = option_seed.is_correct;

    IF matched_questions <> 50 THEN
        RAISE EXCEPTION 'Expected 50 active published general quiz questions, found %', matched_questions;
    END IF;
    IF matched_options <> 131 THEN
        RAISE EXCEPTION 'Expected 131 matched general quiz options, found %', matched_options;
    END IF;
END;
$$;
